// ============================================
// EJEMPLO: src/hooks/useDashboardData.js
// ============================================

import { useState, useEffect } from 'react';
import { clientService } from '../services/clientService';
import { projectService } from '../services/projectService';
import { documentService } from '../services/documentService';

export const useDashboardData = () => {
  const [stats, setStats] = useState({});
  const [clients, setClients] = useState([]);
  const [projects, setProjects] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [clientsData, projectsData, documentsData] = await Promise.all([
        clientService.getAll(),
        projectService.getAll(),
        documentService.getAll(),
      ]);

      setClients(clientsData);
      setProjects(projectsData);
      setDocuments(documentsData);

      // Calcular estadísticas
      setStats({
        total_clients: clientsData.length,
        total_projects: projectsData.length,
        active_projects: projectsData.filter(p => p.status === 'in_progress').length,
        total_documents: documentsData.length,
      });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  return {
    stats,
    clients,
    projects,
    documents,
    loading,
    error,
    refetch: fetchData,
  };
};
